function inferDifficulty(idx: number, total: number): 'easy' | 'medium' | 'hard' {
  const pct = idx / total
  if (pct < 0.35) return 'easy'
  if (pct < 0.75) return 'medium'
  return 'hard'
}

/**
 * Exported question pool in the same format as AP Chemistry.
 * Used by the diagnostic generator for seeded 10-form selection.
 */
/** Item count before the Oct 2026 depth block: legacy items infer difficulty from their position in it. */
const LEGACY_POOL_SIZE = 334

export const apBioQuestionPool: APBioQuestion[] = questionPool.map((q, i) => ({
  question: q.question,
  options: q.options,
  correctAnswer: q.correctIndex,
  explanation: q.explanation,
  difficulty: q.difficulty ?? inferDifficulty(i, LEGACY_POOL_SIZE),
  domain: q.domain ?? TOPIC_TO_DOMAIN[q.topicSlug] ?? 'chemistry-of-life',
  topicSlug: q.topicSlug,
  formSet: q.formSet ?? (i % 3 === 0 ? 'A' : i % 3 === 1 ? 'B' : 'both'),
}))

/* ------------------------------------------------------------------ */
/*  Generator function — used by exit quiz registry                   */
/* ------------------------------------------------------------------ */

/** This pool honours the AP track mixes (track-mix.ts); index.ts reads the flag. */
export const supportsTrackMix = true

export function generateExitQuiz(count: number = 10, topicSlug?: string, difficulty?: string): ExitQuizQuestion[] {
  const source = topicSlug ? relevantPool(questionPool, topicSlug) : questionPool
  // Untracked: the plain shuffle, unchanged (old attempts replay exactly). A
  // track mix reads authored tags only; untagged legacy items count as medium
  // (their apBioQuestionPool tier is positional, not a judgement).
  return drawWithTrackMix(source, count, difficulty, () => shuffle(source).slice(0, count))
    .map((q) => ({
      id: q.id,
      question: q.question,
      options: q.options,
      correctIndex: q.correctIndex,
      explanation: q.explanation,
      category: q.category,
      partNumber: q.part,
    }))
}
